import { notFound } from 'next/navigation';
import { getBuilderBySlug, mockBuilders } from '@/data/mock-data';
import { BuilderProfileClient } from '@/components/profile/BuilderProfileClient';

// Generate static paths for all builders
export function generateStaticParams() {
    return mockBuilders.map((builder) => ({
        slug: builder.slug,
    }));
}

// Generate metadata for SEO
export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }) {
    const { slug } = await params;
    const builder = getBuilderBySlug(slug);

    if (!builder) {
        return { title: 'Builder Not Found' };
    }

    return {
        title: `${builder.name} - Builder Profile | Yobuildplus`,
        description: builder.description.slice(0, 160),
    };
}

export default async function BuilderProfilePage({ params }: { params: Promise<{ slug: string }> }) {
    const { slug } = await params;
    const builder = getBuilderBySlug(slug);

    if (!builder) {
        notFound();
    }

    return <BuilderProfileClient builder={builder} />;
}
